-- Velmora product gallery images from Unsplash.
-- Adds a JSONB array named images with three image URLs per product.
-- Illustrative editorial imagery; verify exact SKU/product match before production.

ALTER TABLE public.products
ADD COLUMN IF NOT EXISTS images jsonb NOT NULL DEFAULT '[]'::jsonb;

UPDATE public.products AS p
SET images = v.images
FROM (VALUES
  ('VLM-001', jsonb_build_array('https://images.unsplash.com/photo-1741250781111-495c70c21b95?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1668873882581-6e0784eee43b?auto=format&fit=crop&w=1200&q=80', 'https://images.unsplash.com/photo-1649172850684-4ccdd44127e6?auto=format&fit=crop&w=1200&q=80')),
